    }

    function authorizeVoter(address _voter) public ownerOnly {
        require(!voters[_voter].voted, "The voter has already voted.");
        voters[_voter].authorized = true;
    }

    function vote(uint _voteIndex) public {
        require(!voters[msg.sender].voted, "You have already voted.");
        require(voters[msg.sender].authorized, "You are not authorized to vote.");

        voters[msg.sender].vote = _voteIndex;
        voters[msg.sender].voted = true;
        voters[msg.sender].voteCount = candidates[_voteIndex].voteCount + 1;
        totalVotes++;

        candidates[_voteIndex].voteCount = voters[msg.sender].voteCount;
    }

    function end() public ownerOnly {
        // Logic to end the election and declare the winner
    }

    function getTotalVotes() public view returns (uint) {
        return totalVotes;
    }

    function getCandidate(uint _index) public view returns (string memory, uint) {
        return (candidates[_index].name, candidates[_index].voteCount);
    }
}
```

This smart contract includes basic functionality for a voting system, such as adding candidates, authorizing voters, casting votes, and ending the election. It also includes functions to retrieve the total number of votes and the details of each candidate. The `ownerOnly` modifier ensures that only the contract creator can add candidates and end the election.

